INSERT INTO `editorial_strategies` (`id`, `status`, `customer_id`, `objectives`, `audience`, `tone`, `pillars`, `dos_donts`, `notes`, `created_at`, `created_by`, `updated_at`, `updated_by`) VALUES ('1','1','4','Piu\' coperti a pranzo nei giorni feriali; far conoscere i piatti d\'autunno.','Impiegati e professionisti della zona (pranzo), coppie e famiglie del quartiere (cena).','familiare, caldo, un po\' ironico; mai tecnico','Piatto della settimana\nDietro le quinte in cucina\nRecensioni dei clienti\nEventi e serate','Si: foto vere dei piatti, prezzi chiari. No: foto di repertorio, troppi hashtag.',NULL,'2026-10-23 00:56:08',NULL,NULL,NULL);
